function buildD(){const all=withKm(),ms=[...new Set(all.map(e=>mo(e.d)))].sort(),lm=ms[ms.length-1],r2=x=>x==null?null:Math.round(x*100)/100;
 return{objectif_dh_km:S.obj||null,budget_mensuel:S.bud||null,mois:ms.map(m=>{const a=agg(all.filter(e=>mo(e.d)===m),all);return{mois:m,dh:r2(a.m),litres:r2(a.l),km:a.km,dh_km:r2(a.dkm),km_jour:r2(a.kj)}}),livreurs_dernier_mois:V.map((v,i)=>{const a=agg(all.filter(e=>e.v===i&&mo(e.d)===lm),all);return{nom:v[0],dh:r2(a.m),km:a.km,dh_km:r2(a.dkm)}}).filter(x=>x.km>0),alertes:AL.slice(0,15)}}
function localSum(D){const m=D.mois,L=[];if(m.length){const c=m[m.length-1];L.push(`• ${ML(c.mois)} : dépense ${n(c.dh)} DH, ${n(c.km)} km, coût moyen ${n(c.dh_km,2)} DH/km.`);if(m.length>1){const p=m[m.length-2];if(p.dh_km&&c.dh_km){const x=(c.dh_km/p.dh_km-1)*100;L.push(`• Le coût DH/km ${x>0?"augmente":"baisse"} de ${n(Math.abs(x),1)}% par rapport à ${ML(p.mois)}.`)}}
  if(D.objectif_dh_km&&c.dh_km)L.push(c.dh_km>D.objectif_dh_km?`• Le coût dépasse l'objectif de ${n(D.objectif_dh_km,2)} DH/km.`:`• Le coût respecte l'objectif de ${n(D.objectif_dh_km,2)} DH/km.`)}
 const lv=D.livreurs_dernier_mois.filter(x=>x.dh_km).sort((a,b)=>a.dh_km-b.dh_km);if(lv.length>1)L.push(`• Meilleur livreur : ${lv[0].nom} (${n(lv[0].dh_km,2)} DH/km) ; à surveiller : ${lv[lv.length-1].nom} (${n(lv[lv.length-1].dh_km,2)} DH/km).`);
 if(D.budget_mensuel&&m.length){const c=m[m.length-1];L.push(c.dh>D.budget_mensuel?`• Budget dépassé de ${n(c.dh-D.budget_mensuel)} DH (budget ${n(D.budget_mensuel)} DH).`:`• Budget respecté : il reste ${n(D.budget_mensuel-c.dh)} DH.`)}if(D.alertes.length)L.push("• Alertes principales : "+D.alertes.slice(0,3).join(" ; ")+".");return L.length?L.join("\n"):"Pas encore assez de données pour un résumé."}
async function PJL(f){const rd=b=>new Promise(r=>{const x=new FileReader();x.onload=()=>r(x.result);x.readAsDataURL(b)});if(f.type.startsWith("image/")){const u=await rd(f),im=new Image();await new Promise(r=>{im.onload=r;im.src=u});const s=Math.min(1,900/Math.max(im.width,im.height)),c=document.createElement("canvas");c.width=im.width*s;c.height=im.height*s;c.getContext("2d").drawImage(im,0,0,c.width,c.height);return c.toDataURL("image/jpeg",.6)}const u=await rd(f);if(u.length>170000){toast("PDF trop lourd (max ~120 Ko)");return""}return u}
