async function gen(){const o=$("ao");let D;try{D=buildD()}catch(e){o.textContent="Données insuffisantes pour un résumé.";return}
 const loc=localSum(D);o.textContent=loc+"\n\n✓ Résumé automatique mis à jour à "+new Date().toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"});return;
 o.textContent=loc+"\n\n⏳ Analyse IA en cours…";
 try{const sm=await claude.use("sample");if(!sm)throw{code:"non disponible dans cette vue"};
  const r=await sm("Tu es analyste de flotte automobile. Rédige en français, ton professionnel, un résumé de 5 à 7 lignes pour la direction : évolution du coût DH/km et de la dépense entre les mois, livreurs à surveiller, alertes importantes, puis 2 recommandations concrètes. N'invente aucun chiffre. Données JSON : "+JSON.stringify(D),{modelTier:"default"});o.textContent=r.text+"\n\n✨ Résumé IA, mis à jour automatiquement."}
 catch(e){o.textContent=loc+"\n\n(Résumé automatique — IA indisponible : "+(e&&(e.code||e.message)||"erreur")+")"}}
