const saveKM=()=>{try{localStorage.setItem(KMK,JSON.stringify(KM))}catch(e){}clearTimeout(window._tk);window._tk=setTimeout(()=>{try{DB&&DB.doc("config/km").set({data:JSON.stringify(KM)})}catch(e){}},600)};
let KMFm=null;
const pm1=m=>{const[y,a]=m.split("-").map(Number),d=new Date(y,a-2,1);return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")};
function kmMonths(){const s=new Set(E.map(e=>mo(e.d)));Object.keys(KM).forEach(m=>s.add(m));s.add(new Date().toISOString().slice(0,7));return[...s].sort()}
function kmVal(m,nm,k){const r=KM[m]&&KM[m][nm];return r&&r[k]!==""&&r[k]!=null&&!isNaN(r[k])?+r[k]:null}
function kmStart(m,nm){const v=kmVal(m,nm,"d");if(v!=null)return[v,false];const p=kmVal(pm1(m),nm,"f");return p!=null?[p,true]:[null,false]}
function renderKm(){const sel=$("kmm");if(!sel)return;const ms=kmMonths(),fm=$("fm").value;
 if(fm&&fm!==KMFm){KMFm=fm;sel.value=fm}
 if(!/^\d{4}-\d{2}$/.test(sel.value))sel.value=ms[ms.length-1];
 const m=sel.value,pv=pm1(m),all=withKm(),vk={};
 all.filter(e=>mo(e.d)===m).forEach(e=>{vk[e.v]=(vk[e.v]||0)+(e.km||0)});
 let tot=0,ok=0,pt=0,pk=0,h="<tr><th class='l'>Livreur</th><th class='l'>Matricule</th><th>Km début de mois</th><th>Km fin de mois</th><th>Km parcourus</th><th>Km d’après les pleins</th></tr>";
 V.forEach((v,i)=>{const nm=v[0],st=kmStart(m,nm),s=st[0],auto=st[1],f=kmVal(m,nm,"f"),r=(KM[m]&&KM[m][nm])||{},km=(s!=null&&f!=null)?f-s:null,bad=km!=null&&km<0;
  if(km!=null&&!bad){tot+=km;ok++}
  const ps=kmStart(pv,nm)[0],pf=kmVal(pv,nm,"f");if(ps!=null&&pf!=null&&pf>=ps){pt+=pf-ps;pk++}
  h+=`<tr><td class="l">${nm}${v[12]?` <span class="mut">· ${v[12]}</span>`:""}</td><td class="l">${v[1]||"–"}</td><td><input class="kmi${auto?" auto":""}" type="number" min="0" inputmode="numeric" data-kn="${i}" data-kk="d" value="${r.d!=null&&r.d!==""?r.d:""}" placeholder="${s!=null?s:""}"></td><td><input class="kmi" type="number" min="0" inputmode="numeric" data-kn="${i}" data-kk="f" value="${r.f!=null&&r.f!==""?r.f:""}"></td><td style="font-weight:700"${bad?' class="kmw"':""}>${km==null?"–":bad?"⚠️ fin < début":n(km)+" km"}</td><td class="mut">${vk[i]?n(vk[i])+" km":"–"}</td></tr>`});
 h+=`<tr style="font-weight:700"><td class="l" colspan="4">Total flotte (${ok}/${V.length} véhicules renseignés)</td><td>${n(tot)} km</td><td>${n(Object.values(vk).reduce((a,b)=>a+b,0))} km</td></tr>`;
 $("kmtb").innerHTML=h;
 const avg=ok?tot/ok:null,dl2=(pk&&pt&&ok)?(tot-pt)/pt*100:null;
 $("kmk").innerHTML=`<div class="k"><i>🛣️</i><b>${n(tot)} km</b><span>Total parcouru par la flotte</span></div><div class="k"><i>🚚</i><b>${n(avg)} km</b><span>Moyenne par véhicule</span></div><div class="k"><i>📆</i><b>${ok}/${V.length}</b><span>Véhicules renseignés</span>${dl2!=null?`<em class="${dl2>0?"up":"dn"}">${dl2>0?"▲":"▼"} ${n(Math.abs(dl2),1)}% vs ${ML(pv)}</em>`:""}</div>`}
const nm1=m=>{const[y,a]=m.split("-").map(Number),d=new Date(y,a,1);return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")};
